create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','admin','manager','staff');
create type public.payment_method as enum ('cash','mobile_money','card','bank','credit','other');
create type public.inventory_movement_type as enum ('purchase','sale','adjustment','return');
create table public.businesses (id uuid primary key default gen_random_uuid(), name text not null, country_code text not null, currency_code text not null, timezone text not null, locale text not null, business_type text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.business_members (business_id uuid references public.businesses(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, role public.member_role not null default 'staff', created_at timestamptz not null default now(), primary key (business_id,user_id));
create table public.product_categories (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null);
create table public.products (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, category_id uuid references public.product_categories(id), name text not null, sku text, description text, selling_price numeric(14,2) not null check (selling_price >= 0), cost_price numeric(14,2) not null check (cost_price >= 0), stock_quantity integer not null default 0, low_stock_threshold integer not null default 0, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customers (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null, phone text, email text, notes text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.sales (id uuid primary key, business_id uuid not null references public.businesses(id) on delete cascade, customer_id uuid references public.customers(id), subtotal numeric(14,2) not null, discount numeric(14,2) not null default 0, total numeric(14,2) not null, payment_status text not null default 'paid', payment_method public.payment_method not null, idempotency_key text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (business_id,idempotency_key));
create table public.sale_items (id uuid primary key default gen_random_uuid(), sale_id uuid not null references public.sales(id) on delete restrict, product_id uuid not null references public.products(id) on delete restrict, quantity integer not null check (quantity > 0), unit_price numeric(14,2) not null, unit_cost numeric(14,2) not null, total numeric(14,2) not null);
create table public.payments (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, sale_id uuid references public.sales(id), customer_id uuid references public.customers(id), amount numeric(14,2) not null check (amount > 0), payment_method public.payment_method not null, payment_date timestamptz not null default now());
create table public.expense_categories (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null);
create table public.expenses (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, category_id uuid references public.expense_categories(id), amount numeric(14,2) not null check (amount > 0), description text not null default '', payment_method public.payment_method not null, expense_date date not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.inventory_movements (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, product_id uuid not null references public.products(id) on delete restrict, type public.inventory_movement_type not null, quantity integer not null check (quantity <> 0), reference_type text, reference_id uuid, created_at timestamptz not null default now());
create table public.business_settings (business_id uuid primary key references public.businesses(id) on delete cascade, settings jsonb not null default '{}');
create table public.subscriptions (business_id uuid primary key references public.businesses(id) on delete cascade, plan text not null default 'free', limits jsonb not null default '{}', status text not null default 'active', current_period_end timestamptz);
create table public.ai_conversations (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, user_id uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.ai_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.ai_conversations(id) on delete cascade, role text not null check (role in ('user','assistant','system')), content text not null, verified_data jsonb, created_at timestamptz not null default now());
create index on public.products(business_id, active); create index on public.customers(business_id); create index on public.sales(business_id, created_at); create index on public.sale_items(product_id); create index on public.expenses(business_id, expense_date); create index on public.inventory_movements(business_id, product_id, created_at);
create or replace function public.is_business_member(target_business uuid) returns boolean language sql security definer set search_path = public as $$ select exists (select 1 from public.business_members where business_id = target_business and user_id = auth.uid()); $$;
alter table public.businesses enable row level security; alter table public.business_members enable row level security; alter table public.products enable row level security; alter table public.customers enable row level security; alter table public.sales enable row level security; alter table public.sale_items enable row level security; alter table public.payments enable row level security; alter table public.expenses enable row level security; alter table public.inventory_movements enable row level security; alter table public.business_settings enable row level security; alter table public.subscriptions enable row level security; alter table public.ai_conversations enable row level security; alter table public.ai_messages enable row level security;
create policy business_members_only on public.businesses for all using (id = any (select business_id from public.business_members where user_id = auth.uid())) with check (id = any (select business_id from public.business_members where user_id = auth.uid()));
do $$ declare t text; begin foreach t in array array['products','customers','sales','payments','expenses','inventory_movements','business_settings','subscriptions','ai_conversations'] loop execute format('create policy member_access_%s on public.%s for all using (public.is_business_member(business_id)) with check (public.is_business_member(business_id))', t, t); end loop; end $$;
create policy member_access_business_members on public.business_members for select using (user_id = auth.uid() or public.is_business_member(business_id));
create policy member_access_sale_items on public.sale_items for all using (exists (select 1 from public.sales s where s.id = sale_id and public.is_business_member(s.business_id))) with check (exists (select 1 from public.sales s where s.id = sale_id and public.is_business_member(s.business_id)));
create policy member_access_ai_messages on public.ai_messages for all using (exists (select 1 from public.ai_conversations c where c.id = conversation_id and public.is_business_member(c.business_id))) with check (exists (select 1 from public.ai_conversations c where c.id = conversation_id and public.is_business_member(c.business_id)));
